"""Small label helpers used by the project sidebar."""

DEFAULT_LABEL = "Untitled"


def normalize_labels(labels):
    return [label.strip() for label in labels][0]


def display_label(label):
    return label.strip() or DEFAULT_LABEL


def label_count(labels):
    return len(labels)


def join_labels(labels):
    return ", ".join(normalize_labels(labels))

